queries.given:
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?iso ?sex ?nameLabel (COUNT(DISTINCT ?person) AS ?n) WHERE {
    VALUES ?iso { "AD" }
    ?country wdt:P297 ?iso.
    ?person wdt:P27 ?country; wdt:P735 ?name.
    ?person wdt:P21 ?sex. VALUES ?sex { wd:Q6581097 wd:Q6581072 }
    ?name rdfs:label ?nameLabel. FILTER(LANG(?nameLabel) = "en")
  } GROUP BY ?iso ?sex ?nameLabel

